create table wksp_dtesc.sgt_ot_asignacion (
    id                     number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment
    by 1 cache 20 noorder nocycle nokeep noscale not null enable,
    ot_id                  number not null enable,
    usuario_asignado       varchar2(255 byte) not null enable,
    asignado_por           varchar2(255 byte) not null enable,
    instrucciones_jefatura varchar2(1000 byte) not null enable,
    es_principal           char(1 byte) default 'Y' not null enable,
    fecha_asignacion       timestamp(6) default systimestamp not null enable,
    fecha_lectura          timestamp(6),
    creado_el              timestamp(6) default systimestamp
);

alter table wksp_dtesc.sgt_ot_asignacion
    add constraint chk_sgt_ot_asig_prin
        check ( es_principal in ( 'Y', 'N' ) ) enable;

alter table wksp_dtesc.sgt_ot_asignacion add primary key ( id )
    using index enable;


